import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
import { VRMLoaderPlugin, type VRM } from '@pixiv/three-vrm';

// The e2e fixture is generated by scripts/make-fixture-vrm.mjs; this guards it against a broken regeneration.
const bytes = readFileSync(new URL('../../e2e/fixtures/minimal.vrm', import.meta.url));

async function parseFixture() {
  const loader = new GLTFLoader();
  loader.register(parser => new VRMLoaderPlugin(parser));
  const buffer = bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength);
  const gltf = await loader.parseAsync(buffer, '');
  return gltf.userData.vrm as VRM;
}

describe('e2e fixture VRM', () => {
  it('stays small', () => {
    expect(bytes.byteLength).toBeLessThan(50 * 1024);
  });

  it('parses as VRM 1.0 with meta, a full humanoid, an expression and a spring bone', async () => {
    const vrm = await parseFixture();
    expect(vrm).toBeTruthy();
    const meta = vrm.meta;
    if (meta.metaVersion !== '1') throw new Error(`Expected VRM 1.0 meta, got ${meta.metaVersion}`);
    expect(meta.name).toBe('Deez fixture');
    expect(meta.authors).toEqual(['deac online · Worldbuild.io']);
    expect(meta.licenseUrl).toBe('https://vrm.dev/licenses/1.0/');
    for (const bone of ['hips', 'spine', 'head', 'leftUpperArm', 'leftHand', 'rightLowerLeg', 'rightFoot'] as const) {
      expect(vrm.humanoid.getRawBoneNode(bone), bone).toBeTruthy();
    }
    expect(vrm.expressionManager?.getExpression('happy')).toBeTruthy();
    expect(vrm.springBoneManager?.joints.size).toBe(2);
    expect(vrm.springBoneManager?.colliderGroups.length).toBe(1);
  });
});
